function resetInspection(){model.restore();el<HTMLSelectElement>('category').value='';el<HTMLSelectElement>('level-filter').value='';input('cut').checked=false;input('edges').checked=false;model.setTransparency(false);input('transparent').checked=false;syncMode();}
