function setCamera(position:T.Vector3,target:T.Vector3,smooth=true){if(smooth)transition={from:camera.position.clone(),to:position,fromTarget:orbit.target.clone(),toTarget:target,start:performance.now()};else{camera.position.copy(position);orbit.target.copy(target);camera.lookAt(target);orbit.update();}}
