async function chooseMode(next:Mode,level=currentLevel){if(!ready)return;pause();transition=null;
  if(next==='walk'){
    if(model.inspection()||input('transparent').checked){resetInspection();toast('Modelo integral restaurado e cortes desativados para caminhar com colisões coerentes.');}
    el('status').textContent='Validando apoio e altura livre…';
    const g=generation,p=await physics.findEntry(model,level,mode==='fly'?camera.position.clone():undefined);if(g!==generation)return;
    if(!p||!physics.teleport(p,level)){physics.suspend();mode='fly';flyAtLevel(level);toast('Não foi encontrado um apoio com espaço livre para a cápsula neste nível. Modo Voar ativado.');}else{mode='walk';camera.position.copy(physics.eye());currentLevel=level;}
  }else{physics.suspend();mode=next;if(next==='orbit'){orbit.target.copy(camera.position).add(camera.getWorldDirection(new T.Vector3()).multiplyScalar(5));orbit.update();}}
  if(mode!=='orbit'){const direction=camera.getWorldDirection(new T.Vector3());yaw=Math.atan2(-direction.x,-direction.z);pitch=mode==='walk'?0:Math.asin(T.MathUtils.clamp(direction.y,-1,1));camera.rotation.set(pitch,yaw,0,'YXZ');el('levels').classList.add('collapsed');el('properties').classList.add('collapsed');}
  el('status').textContent='Modelo pronto';syncMode();updateLevelLabel();
}
function flyAtLevel(level:number|null){const l=meta?.levels.find(l=>l.id===level),b=model.bounds,c=b.getCenter(new T.Vector3());camera.position.set(c.x,(l?.worldY??c.y)+1.65,b.max.z+1);camera.lookAt(c.x,camera.position.y,c.z);yaw=camera.rotation.y;pitch=camera.rotation.x;}
function updateLevelLabel(){const l=meta?.levels.find(l=>l.id===currentLevel);el('level-label').textContent=l?`${l.name} · #${l.id}`:'Modelo integral';document.querySelectorAll('.level-row').forEach(e=>e.classList.toggle('active',Number((e as HTMLElement).dataset.id)===currentLevel));}
